B.aS_=new A.bI("major_18","\u041b\u0443\u043d\u0430","XVIII","Major Arcana","\u0421\u0442\u0430\u0440\u0448\u0438\u0435 \u0430\u0440\u043a\u0430\u043d\u044b","\u0412\u043e\u0434\u0430","",B.asu,"\u041b\u0443\u043d\u0430 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u043a\u0440\u0438\u0437\u0438\u0441 \u0432\u0435\u0440\u044b \u0438 \u0433\u043b\u0443\u0431\u043e\u043a\u0438\u0445 \u044d\u043c\u043e\u0446\u0438\u0439. \u042d\u0442\u043e \u0432\u0440\u0435\u043c\u044f, \u043a\u043e\u0433\u0434\u0430 \u0432\u0441\u0435 \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u043d\u0435 \u0442\u0430\u043a, \u043a\u0430\u043a \u043a\u0430\u0436\u0435\u0442\u0441\u044f, \u0430 \u0438\u043b\u043b\u044e\u0437\u0438\u0438 \u0438\u043b\u0438 \u0441\u0442\u0440\u0430\u0445\u0438 \u043c\u043e\u0433\u0443\u0442 \u0437\u0430\u0442\u0443\u043c\u0430\u043d\u0438\u0432\u0430\u0442\u044c \u0432\u0430\u0448\u0435 \u0441\u0443\u0436\u0434\u0435\u043d\u0438\u0435. \u041b\u0443\u043d\u0430 \u043f\u0440\u043e\u0441\u0438\u0442 \u0432\u0430\u0441 \u0434\u043e\u0432\u0435\u0440\u044f\u0442\u044c \u0441\u0432\u043e\u0435\u0439 \u0438\u043d\u0442\u0443\u0438\u0446\u0438\u0438 \u0438 \u043e\u0441\u0442\u043e\u0440\u043e\u0436\u043d\u043e \u043f\u0440\u0435\u043e\u0434\u043e\u043b\u0435\u0432\u0430\u0442\u044c \u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u044c. \u041e\u0431\u0440\u0430\u0442\u0438\u0442\u0435 \u0432\u043d\u0438\u043c\u0430\u043d\u0438\u0435 \u043d\u0430 \u0441\u0432\u043e\u0438 \u043c\u0435\u0447\u0442\u044b \u0438 \u043f\u043e\u0434\u0441\u043e\u0437\u043d\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u043f\u043e\u0441\u043b\u0430\u043d\u0438\u044f.","\u0412 \u043f\u0435\u0440\u0435\u0432\u0435\u0440\u043d\u0443\u0442\u043e\u043c \u043f\u043e\u043b\u043e\u0436\u0435\u043d\u0438\u0438 \u041b\u0443\u043d\u0430 \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442, \u0447\u0442\u043e \u0438\u043b\u043b\u044e\u0437\u0438\u0438 \u0440\u0430\u0441\u0441\u0435\u0438\u0432\u0430\u044e\u0442\u0441\u044f \u0438 \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u044f\u0441\u043d\u043e\u0441\u0442\u044c. \u0421\u0442\u0440\u0430\u0445\u0438, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043a\u0430\u0437\u0430\u043b\u0438\u0441\u044c \u043d\u0435\u043f\u0440\u0435\u043e\u0434\u043e\u043b\u0438\u043c\u044b\u043c\u0438, \u0443\u043c\u0435\u043d\u044c\u0448\u0430\u044e\u0442\u0441\u044f, \u0438 \u0432\u044b \u043d\u0430\u0447\u0438\u043d\u0430\u0435\u0442\u0435 \u0432\u0438\u0434\u0435\u0442\u044c \u043f\u0440\u0430\u0432\u0434\u0443 \u043e \u0441\u0438\u0442\u0443\u0430\u0446\u0438\u0438.","\u041f\u043e\u043b\u043d\u0430\u044f \u043b\u0443\u043d\u0430 \u0441\u0438\u044f\u0435\u0442 \u043c\u0435\u0436\u0434\u0443 \u0434\u0432\u0443\u043c\u044f \u0431\u0430\u0448\u043d\u044f\u043c\u0438, \u043e\u0441\u0432\u0435\u0449\u0430\u044f \u0442\u0440\u043e\u043f\u0443, \u043a\u043e\u0442\u043e\u0440\u0430\u044f \u0432\u044c\u0435\u0442\u0441\u044f \u043c\u0435\u0436\u0434\u0443 \u0441\u043e\u0431\u0430\u043a\u043e\u0439 \u0438 \u0432\u043e\u043b\u043a\u043e\u043c, \u043c\u0438\u043c\u043e \u0440\u0430\u043a\u0430, \u0432\u044b\u0445\u043e\u0434\u044f\u0449\u0435\u0433\u043e \u0438\u0437 \u043f\u0440\u0443\u0434\u0430. \u041b\u0438\u0446\u043e \u041b\u0443\u043d\u044b \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u0432\u043d\u0438\u0437 \u0441 \u0432\u044b\u0440\u0430\u0436\u0435\u043d\u0438\u0435\u043c \u0442\u0430\u0439\u043d\u044b. \u0421\u0446\u0435\u043d\u0430 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u0431\u0435\u0441\u0441\u043e\u0437\u043d\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0435 \u0438 \u0446\u0430\u0440\u0441\u0442\u0432\u043e \u0441\u043d\u043e\u0432.","\u0414\u043e\u0432\u0435\u0440\u044f\u0439\u0442\u0435 \u0441\u0432\u043e\u0435\u0439 \u0438\u043d\u0442\u0443\u0438\u0446\u0438\u0438 \u0432 \u0442\u0435\u043c\u043d\u043e\u0442\u0435.","assets/tarot/m18.jpg")
B.ar0=s(["\u0420\u0430\u0434\u043e\u0441\u0442\u044c","\u0423\u0441\u043f\u0435\u0445","\u0416\u0438\u0437\u043d\u0435\u043d\u043d\u0430\u044f \u0441\u0438\u043b\u0430","\u042f\u0441\u043d\u043e\u0441\u0442\u044c","\u041e\u043f\u0442\u0438\u043c\u0438\u0437\u043c"],t.s)
B.aSf=new A.bI("major_19","\u0421\u043e\u043b\u043d\u0446\u0435","XIX","Major Arcana","\u0421\u0442\u0430\u0440\u0448\u0438\u0435 \u0430\u0440\u043a\u0430\u043d\u044b","\u041e\u0433\u043e\u043d\u044c","\u0421\u043e\u043b\u043d\u0446\u0435",B.ar0,"\u0421\u043e\u043b\u043d\u0446\u0435 \u043f\u0440\u0438\u043d\u043e\u0441\u0438\u0442 \u0440\u043e\u0441\u0442, \u0432\u044b\u0437\u0434\u043e\u0440\u043e\u0432\u043b\u0435\u043d\u0438\u0435 \u0438 \u0431\u043b\u0435\u0441\u0442\u044f\u0449\u0438\u0439 \u0443\u0441\u043f\u0435\u0445. \u042d\u0442\u043e \u043e\u0434\u043d\u0430 \u0438\u0437 \u0441\u0430\u043c\u044b\u0445 \u043f\u043e\u0437\u0438\u0442\u0438\u0432\u043d\u044b\u0445 \u043a\u0430\u0440\u0442 \u0422\u0430\u0440\u043e, \u043f\u0440\u0435\u0434\u0432\u0435\u0449\u0430\u044e\u0449\u0430\u044f \u0432\u0440\u0435\u043c\u044f \u0440\u0430\u0434\u043e\u0441\u0442\u0438, \u044f\u0441\u043d\u043e\u0441\u0442\u0438 \u0438 \u0434\u043e\u0441\u0442\u0438\u0436\u0435\u043d\u0438\u0439. \u041f\u043e\u0434 \u0432\u043b\u0438\u044f\u043d\u0438\u0435\u043c \u0421\u043e\u043b\u043d\u0446\u0430 \u0440\u0430\u0441\u0446\u0432\u0435\u0442\u0430\u044e\u0442 \u0434\u0435\u0442\u0438, \u0442\u0432\u043e\u0440\u0447\u0435\u0441\u0442\u0432\u043e \u0438 \u043d\u043e\u0432\u044b\u0435 \u043f\u0440\u043e\u0435\u043a\u0442\u044b. \u042d\u0442\u043e \u0432\u0440\u0435\u043c\u044f \u043e\u0442\u043f\u0440\u0430\u0437\u0434\u043d\u043e\u0432\u0430\u0442\u044c \u0441\u0432\u043e\u0438 \u0434\u043e\u0441\u0442\u0438\u0436\u0435\u043d\u0438\u044f \u0438 \u043f\u0440\u0438\u043d\u044f\u0442\u044c \u0442\u0435\u043f\u043b\u043e \u0438 \u0438\u0437\u043e\u0431\u0438\u043b\u0438\u0435 \u0436\u0438\u0437\u043d\u0438.","\u041f\u0440\u0438 \u043f\u0435\u0440\u0435\u0432\u043e\u0440\u043e\u0442\u0435 \u044d\u043d\u0435\u0440\u0433\u0438\u044f \u0421\u043e\u043b\u043d\u0446\u0430 \u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e \u0431\u043b\u043e\u043a\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0438\u043b\u0438 \u0443\u043c\u0435\u043d\u044c\u0448\u0430\u0435\u0442\u0441\u044f. \u0412\u043e\u0437\u043c\u043e\u0436\u043d\u043e, \u0432\u044b \u0438\u0441\u043f\u044b\u0442\u044b\u0432\u0430\u0435\u0442\u0435 \u043d\u0435\u0443\u0432\u0435\u0440\u0435\u043d\u043d\u043e\u0441\u0442\u044c \u0432 \u0441\u0435\u0431\u0435 \u0438\u043b\u0438 \u0432\u0440\u0435\u043c\u0435\u043d\u043d\u0443\u044e \u043d\u0435\u0443\u0434\u0430\u0447\u0443. \u0420\u0430\u0434\u043e\u0441\u0442\u044c \u0438 \u0443\u0441\u043f\u0435\u0445 \u043f\u0440\u044f\u043c\u043e\u0433\u043e \u0421\u043e\u043b\u043d\u0446\u0430 \u043f\u043e-\u043f\u0440\u0435\u0436\u043d\u0435\u043c\u0443 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b \u0432\u0430\u043c \u2014 \u043d\u0443\u0436\u043d\u043e \u043b\u0438\u0448\u044c \u0443\u0431\u0440\u0430\u0442\u044c \u0442\u043e, \u0447\u0442\u043e \u0437\u0430\u0433\u043e\u0440\u0430\u0436\u0438\u0432\u0430\u0435\u0442 \u0441\u0432\u0435\u0442.","\u0412 \u043d\u0435\u0431\u0435 \u0441\u0432\u0435\u0442\u0438\u0442 \u0431\u043e\u043b\u044c\u0448\u043e\u0435 \u043b\u0443\u0447\u0435\u0437\u0430\u0440\u043d\u043e\u0435 \u0441\u043e\u043b\u043d\u0446\u0435, \u043b\u0443\u0447\u0438 \u0435\u0433\u043e \u043e\u0434\u043d\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e \u043f\u0440\u044f\u043c\u044b\u0435 \u0438 \u0432\u043e\u043b\u043d\u0438\u0441\u0442\u044b\u0435. \u0420\u0435\u0431\u0435\u043d\u043e\u043a \u0435\u0434\u0435\u0442 \u043d\u0430 \u0431\u0435\u043b\u043e\u0439 \u043b\u043e\u0448\u0430\u0434\u0438, \u0440\u0430\u0434\u043e\u0441\u0442\u043d\u043e \u0440\u0430\u0441\u043a\u0438\u043d\u0443\u0432 \u0440\u0443\u043a\u0438, \u0432 \u0432\u0435\u043d\u043a\u0435 \u0438\u0437 \u0446\u0432\u0435\u0442\u043e\u0432. \u041f\u043e\u0437\u0430\u0434\u0438 \u043d\u0438\u0445 \u043d\u0430\u0434 \u0441\u0430\u0434\u043e\u0432\u043e\u0439 \u0441\u0442\u0435\u043d\u043e\u0439 \u0446\u0432\u0435\u0442\u0443\u0442 \u043f\u043e\u0434\u0441\u043e\u043b\u043d\u0443\u0445\u0438. \u0421\u0446\u0435\u043d\u0430 \u0438\u0437\u043b\u0443\u0447\u0430\u0435\u0442 \u0447\u0438\u0441\u0442\u043e\u0435 \u0441\u0447\u0430\u0441\u0442\u044c\u0435 \u0438 \u0436\u0438\u0437\u043d\u0435\u043d\u043d\u0443\u044e \u0441\u0438\u043b\u0443.","\u041f\u0443\u0441\u0442\u044c \u0442\u0432\u043e\u0439 \u0441\u0432\u0435\u0442 \u0441\u0438\u044f\u0435\u0442.","assets/tarot/m19.jpg")
